class DxRandom {
 public:
  static constexpr std::size_t state_words = 624;

  GAME_HD void seed(std::uint32_t value);
  GAME_HD std::uint32_t raw_u32();
  GAME_HD std::uint32_t get_rand(std::uint32_t maximum);

  GAME_HD const array<std::uint32_t, state_words>& state() const { return state_; }
  GAME_HD std::uint32_t index() const { return index_; }
  GAME_HD void restore(const array<std::uint32_t, state_words>& state,
               std::uint32_t index);

 private:
  GAME_HD void twist();

  array<std::uint32_t, state_words> state_{};
  std::uint32_t index_{state_words};
};


inline constexpr std::size_t kPeriodOffset=397;
inline constexpr std::uint32_t kMatrixA=0x9908b0dfU;
GAME_HD inline void DxRandom::seed(std::uint32_t value) {
  for (auto& word : state_) {
    const std::uint32_t following = 69'069U * value + 1U;
    word = (value & 0xffff0000U) | (following >> 16U);
    value = 69'069U * following + 1U;
  }
  index_ = state_words;
}

GAME_HD inline void DxRandom::twist() {
  for (std::size_t index = 0; index < state_words - kPeriodOffset; ++index) {
    const std::uint32_t joined =
        (state_[index] & 0x80000000U) | (state_[index + 1] & 0x7fffffffU);
    state_[index] = state_[index + kPeriodOffset] ^ (joined >> 1U) ^
                    ((joined & 1U) != 0U ? kMatrixA : 0U);
  }
  for (std::size_t index = state_words - kPeriodOffset;
       index < state_words - 1; ++index) {
    const std::uint32_t joined =
        (state_[index] & 0x80000000U) | (state_[index + 1] & 0x7fffffffU);
    state_[index] = state_[index + kPeriodOffset - state_words] ^
                    (joined >> 1U) ^ ((joined & 1U) != 0U ? kMatrixA : 0U);
  }
  const std::uint32_t joined =
      (state_.back() & 0x80000000U) | (state_.front() & 0x7fffffffU);
  state_.back() = state_[kPeriodOffset - 1] ^ (joined >> 1U) ^
                  ((joined & 1U) != 0U ? kMatrixA : 0U);
  index_ = 0;
}

GAME_HD inline std::uint32_t DxRandom::raw_u32() {
  if (index_ >= state_words) twist();
  std::uint32_t value = state_[index_++];
  value ^= value >> 11U;
  value ^= (value << 7U) & 0x9d2c5680U;
  value ^= (value << 15U) & 0xefc60000U;
  value ^= value >> 18U;
  return value;
}

GAME_HD inline std::uint32_t DxRandom::get_rand(std::uint32_t maximum) {
  if (maximum > 0x7fffffffU) {
    return 0;
  }
  return static_cast<std::uint32_t>(
      (static_cast<std::uint64_t>(raw_u32()) *
       (static_cast<std::uint64_t>(maximum) + 1U)) >>
      32U);
}

GAME_HD inline void DxRandom::restore(
    const array<std::uint32_t, state_words>& state,
    std::uint32_t index) {
  if (index > state_words) {
    return;
  }
  state_ = state;
  index_ = index;
}


